example:
composition "Fire" { ample 1  tempo 96  master-seed 17 }

curve wave {
  value lfo(1, 0, 1000)
}

fire hit {
  threshold 0.5
  direction rising
  note 48
  length 300 ms
  gap 600 ms
  from wave.level -> input
}

synth bass {
  wave saw
  gain -9 dB
  from hit.notes -> notes
}

master output {
  from bass.audio -> audio
}
